def clasificar_cross_cluster(row):
    if row["x_std"] >= 0 and row["lag_y_std"] >= 0:
        return "Alto-Alto"
    elif row["x_std"] >= 0 and row["lag_y_std"] < 0:
        return "Alto-Bajo"
    elif row["x_std"] < 0 and row["lag_y_std"] >= 0:
        return "Bajo-Alto"
    else:
